{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C02","C10","C31","C35","C12","C20","C33","C15","C19","C22","C25","C26","C27","C32","C06"],
  "contradictory_card_ids": ["C28","C23"],
  "prediction_basis_card_ids": ["C02","C10","C31","C35","C12","C20","C15","C19","C22","C25","C26","C27","C32"],
  "claims": [
    {
      "claim": "The most transferable direct absolute-F records for rigid polycyclic oxygenated molecules are above 20%: lefamulin fasted absolute F is 25.8% (C02, C10), confirmed by population PK Ftot 0.24 (C31) and by the 600 mg oral versus 150 mg IV AUC ratio that dose-normalizes to about 25.8% (C35).",
      "card_ids": ["C02","C10","C31","C35"]
    },
    {
      "claim": "Other rigid polycyclic or polar molecules show high oral F: digitoxin fasted absolute F 90.6-91.2% with 89.7% AUC-based availability (C12, C20, C33), topiramate >80% (C15), dihydroartemisinin 45% in volunteers (C19, C22), and zidovudine 61% in cirrhosis patients (C06).",
      "card_ids": ["C12","C20","C33","C15","C19","C22","C06"]
    },
    {
      "claim": "Small polar drugs support that high polarity alone does not imply F below 20%: 5-ISMN about 100% (C25), doxifluridine 34-47% as capsules and 50-80% in rats (C26, C27), and clavulanic acid 98% in cats (C32).",
      "card_ids": ["C25","C26","C27","C32"]
    },
    {
      "claim": "The only sub-20% records are tacrolimus about 10% in fasted rats given a PEG solution (C28) and solubility-limited poor DHA bioavailability (C23); both are species, formulation, or solubility specific and do not transfer to the query whose solubility prior is favorable.",
      "card_ids": ["C28","C23"]
    },
    {
      "claim": "The L4 solubility and dissolution records (C49-C60) concern tacrolimus, sirolimus, buparvaquone, simvastatin, SN38, lovastatin, and camptothecin; they describe poorly soluble lipophilic drugs and provide no permeability or F evidence for the query.",
      "card_ids": ["C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59","C60"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C49","C50","C51","C52","C53","C54","C55","C56","C57","C58","C59","C60"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability, AUC, or Cmax data exist for the query molecule.",
    "No query-specific permeability, efflux, or first-pass measurements are available.",
    "L4 solubility and dissolution records are for unrelated poorly soluble drugs and do not address the query permeability-limited absorption.",
    "The physicochemical prior of low logD and high TPSA remains a genuine uncertainty but is not endpoint proof.",
    "Species and formulation dependence of the tacrolimus and DHA low-F records cannot be resolved for the query."
  ],
  "decision_summary": "L4 intestinal absorption and solubility records concern tacrolimus, sirolimus, buparvaquone, simvastatin, SN38, lovastatin, and camptothecin; they provide no query-relevant permeability or F evidence and the query solubility prior is favorable. The best transferable direct F evidence remains above 20% (lefamulin about 25.8%, digitoxin about 90%, topiramate >80%, DHA 45%, and polar small molecules with high F), while the only sub-20% records are species, formulation, or solubility specific. Prediction remains high with moderate confidence."
}

